<?php
declare(strict_types=1);
require __DIR__ . '/action-common.php'; admin_post();
try { $supplierId=filter_var($_POST['fornecedor_so_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($supplierId===false)throw new InvalidArgumentException('Fornecedor inválido.');$supplier=$application->soSuppliers()->findById($supplierId);if(!$supplier)throw new InvalidArgumentException('Fornecedor não encontrado.');if($application->adminCompanies()->integrationBySupplier($supplierId))throw new InvalidArgumentException('Fornecedor já vinculado.');$data=admin_company_data($_POST,null,['contato_responsavel'=>$supplier->contact,'telefone'=>$supplier->phone]);if($application->adminCompanies()->findByDocument($data['documento']))throw new InvalidArgumentException('Documento já cadastrado. Use a opção de vincular a uma empresa existente.');$id=$application->adminCompanies()->import($data,$currentUser->id(),$supplierId);$session->flash('success','Empresa aprovada e cadastrada com sucesso.');admin_action_redirect('adm/empresa.php?id='.$id); } catch(\Throwable $e){admin_action_error($e,'adm/empresa.php?fornecedor_so='.(int)($_POST['fornecedor_so_id']??0));}
